mapper.select:
SELECT a.* FROM services_request_log a WHERE a.request_time BETWEEN #{beginDate} AND #{endDate}
AND a.request_Content LIKE '%'||#{requestContent}||'%' '%'+#{requestContent}+'%' CONCAT('%', #{requestContent}, '%')
AND a.trace_Code=#{traceCode}
AND a.exception_Info LIKE '%'||#{exceptionInfo}||'%' '%'+#{exceptionInfo}+'%' CONCAT('%', #{exceptionInfo}, '%')
AND a.request_ip like '%'||#{requestIp}||'%' '%'+#{requestIp}+'%' CONCAT('%', #{requestIp}, '%')
AND a.server_Ip like '%'||#{serverIp}||'%' '%'+#{serverIp}+'%' CONCAT('%', #{serverIp}, '%')
AND a.exception_Info!=''
AND a.opAction=#{opAction}
ORDER BY a.request_time DESC
